std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::transform(
        result.begin(), result.end(), result.begin(),
        [this](std::size_t /*unused*/, double /*unused*/) {
            // placeholder; overwritten below via index-aware overload
            return 0.0;
        });
    // Real implementation: for each column, accumulate column-c values.
    // We can't use std::accumulate directly on a column without building
    // a strided view, so we use an index-aware transform that walks the
    // column via at() and reduces it with std::accumulate.
    auto col_sum = [this](std::size_t c) {
        double s = 0.0;
        for (std::size_t r = 0; r < rows_; ++r) {
            s += at(r, c);
        }
        return s;
    };
    std::vector<std::size_t> idx(cols_);
    for (std::size_t c = 0; c < cols_; ++c) {
        idx[c] = c;
    }
    std::transform(idx.begin(), idx.end(), result.begin(),
                   [&col_sum](std::size_t c) { return col_sum(c); });
    // Replace the per-column sums with std::accumulate over an index range
    // that produces column elements: for column c, elements are at(0,c),
    // at(1,c), ..., at(rows_-1,c). Build the strided sequence via a
    // generator and let std::accumulate sum it.
    for (std::size_t c = 0; c < cols_; ++c) {
        std::vector<double> col_elems(rows_);
        for (std::size_t r = 0; r < rows_; ++r) {
            col_elems[r] = at(r, c);
        }
        result[c] = std::accumulate(col_elems.begin(), col_elems.end(), 0.0);
    }
    return result;
}

